<?php
/** Proof — the AI statement, cash, items, recurring and the caller's own tools: each answers what the views and functions say; a resolver call (`q` alone) answers a plain list. */
require __DIR__ . '/lib.php';
$W = p4world();
$BEA = 27; $VERA = 26; $CARL = 28; $OWNER = 1;
echo "1. The kernel's AI statement\n";
ok(tdata($BEA, 'ai_statement_status', ['q' => '2026-09']) === [['ai_statement_id' => $W['ai'], 'period' => '2026-09']], 'ai_statement_status q alone: a plain list (ai_statement_id, period)');
$s = tdata($BEA, 'ai_statement_status', ['status' => 'agrees']);
$st = $s['statements'][0] ?? [];
ok(count($s['statements']) === 1 && $st['kernel_status'] === 'closed' && $st['bill_count'] === 2 && $st['late_calls'] === 2 && count($st['bills']) === 2 && array_unique(array_column($st['bills'], 'bill_status')) === ['approved'], 'status agrees: September, closed in the OS, two approved bills, two late calls');
ok(same_money($st['totals']['USD'], val_as($BEA, "SELECT totals->>'USD' FROM mcp_ai_statements WHERE period = '2026-09'")), 'its totals per currency are the view\'s (' . $st['totals']['USD'] . ')');
$ln = tdata($BEA, 'ai_statement_lines', ['period' => '2026-09']);
ok(count($ln['lines']) === 3 && $ln['lines'][0]['amount'] === '12.3456' && $ln['lines'][1]['note'] === '2 late calls', 'ai_statement_lines: the three lines verbatim, amounts at four decimals ("12.3456")');
$g = tdata($BEA, 'ai_statement_lines', ['ai_statement_id' => $W['ai'], 'group_by' => 'provider']);
$an = array_values(array_filter($g['rows'], fn ($r) => $r['group'] === 'anthropic'))[0] ?? [];
ok(count($g['rows']) === 2 && $an['amount'] === '20.0005' && (int) $an['calls'] === 200, 'grouped by provider: Anthropic 20.0005 over 200 calls');
ok(count(tdata($BEA, 'ai_statement_lines', ['period' => '2026-09', 'group_by' => 'department'])['rows']) === 3 && tool($BEA, 'ai_statement_lines', ['period' => '2026-09', 'group_by' => 'nonsense'])['error'], 'by department; an unknown grouping is refused');
$ck = tdata($BEA, 'ai_statement_check', ['period' => '2026-09']);
ok($ck['agrees'] === true && count($ck['rows']) === 2 && array_unique(array_column($ck['rows'], 'agrees')) === [true] && same_money($ck['rows'][0]['difference'], '0.00'), 'ai_statement_check: both providers agree, difference 0.00');
ok(tool($BEA, 'ai_statement_check', ['period' => '2031-01'])['error'], 'an unknown month is a refusal');
echo "2. Cash\n";
$cp = tdata($BEA, 'cash_position', ['as_of' => '2026-12-31']);
$sql = sql_as($BEA, "SELECT bank_account_id, ledger_balance FROM gl_cash_position(DATE '2026-12-31') ORDER BY bank_account_id");
ok(count($cp['accounts']) === count($sql) && same_money($cp['accounts'][0]['ledger_balance'] ?? 'x', $sql[0]['ledger_balance'] ?? 'y') && count($cp['totals']) >= 1, 'cash_position: every bank account\'s balances equal the function; totals per currency');
$ct = tdata($BEA, 'cash_position', ['as_of' => '2026-10-05', 'trend' => true]);
ok(count($ct['trend']) === 12 && end($ct['trend'])['month_end'] === '2026-10-05' && $ct['trend'][0]['month_end'] === '2025-11-30', 'with trend: twelve month-ends, the last the as-of date');
ok(tdata($BEA, 'find_bank_accounts', ['q' => 'Checking']) === [['bank_account_id' => $W['bank'], 'name' => 'SMOKE Checking']], 'find_bank_accounts q alone: a plain list (bank_account_id, name)');
$fb = tdata($BEA, 'find_bank_accounts', ['include_archived' => false]);
ok(count($fb['bank_accounts']) >= 2 && $fb['bank_accounts'][0]['account_code'] !== null && $fb['bank_accounts'][0]['unmatched_lines'] !== null, 'the bank accounts with their ledger account and unmatched count');
$ub = tdata($BEA, 'unmatched_bank_lines', []);
ok(array_column($ub['lines'], 'bank_transaction_id') === [$W['line_xfer'], $W['line_match'], $W['line_open']] && $ub['lines'][0]['txn_date'] === '2026-09-16', 'unmatched_bank_lines: the three lines oldest first');
$q = tdata($BEA, 'unmatched_bank_lines', ['q' => 'SMOKE-REF-75']);
ok(count($q) === 1 && $q[0]['bank_transaction_id'] === $W['line_match'] && str_contains($q[0]['label'], '75.00'), 'q alone resolves a line by its reference as a plain list (bank_transaction_id, label)');
ok(count(tdata($BEA, 'unmatched_bank_lines', ['status' => 'matched'])['lines']) === 0 && count(tdata($BEA, 'unmatched_bank_lines', ['q' => 'FEE', 'bank_account_id' => $W['bank']])['lines']) === 1, 'matched lines: none; a word of the description within an account');
$mc = tdata($BEA, 'match_candidates', ['bank_transaction_id' => $W['line_xfer']]);
$sqlc = sql_as($BEA, 'SELECT item_type, item_id FROM gl_bank_candidates(:t)', ['t' => $W['line_xfer']]);
ok($mc['count'] === count($sqlc) && $mc['count'] === 1 && $mc['candidates'][0]['item_type'] === 'transfer' && $mc['candidates'][0]['item_id'] === $W['transfer'] && abs((float) $mc['candidates'][0]['amount']) === 50.0, 'match_candidates: the -50.00 line could be the 50.00 transfer, exactly the function\'s answer');
ok(tdata($BEA, 'match_candidates', ['bank_transaction_id' => $W['line_open']])['count'] === 0, 'a line nothing in the ledger fits has no candidates (the function\'s rule: to the cent, within five days)');
ok(tool($BEA, 'match_candidates', ['bank_transaction_id' => 999999])['error'], 'an unknown line is a refusal');
$it = tdata($BEA, 'in_transit', ['as_of' => '2026-10-05']);
ok(in_array($W['rcpt_loose'], array_column($it['receipts_undeposited'], 'receipt_id'), true) && in_array($W['deposit'], array_column($it['deposits_unmatched'], 'deposit_id'), true) && in_array($W['payment'], array_column($it['payments_unmatched'], 'payment_id'), true) && in_array($W['transfer'], array_column($it['transfers_unmatched'], 'transfer_id'), true), 'in_transit: the loose receipt, the deposit, the cheque and the transfer — recorded in the ledger, not yet on a bank line');
ok(count(tdata($BEA, 'find_reconciliations', ['q' => '2026-09'])) === 0 && tdata($BEA, 'find_reconciliations', [])['count'] === 0, 'find_reconciliations: none yet; a date nobody has resolves to an empty list');
$tr = tdata($BEA, 'find_transfers', ['bank_account_id' => $W['cash']]);
ok($W['transfer'] > 0 && count($tr['transfers']) === 1 && same_money($tr['transfers'][0]['amount'], '50.00') && $tr['transfers'][0]['to_bank_name'] === 'SMOKE Petty cash', 'find_transfers: the 50.00 transfer to petty cash');
ok(count(tdata($BEA, 'find_transfers', ['q' => $tr['transfers'][0]['number']])) === 1, 'q alone resolves a transfer by number');
echo "3. Items, tax rates, recurring\n";
[$ic, $ib] = act(as_member(1), '/settings/items/save.php', ['code' => 'SMK-1', 'name' => 'SMOKE Widget', 'kind' => 'product', 'unit' => 'each', 'unit_price' => '12.50', 'income_account' => account_id('4100')]);
$fi = tdata($BEA, 'find_items', ['q' => 'Widget']);
ok($fi === [['item_id' => (int) one("SELECT id FROM items WHERE code = 'SMK-1'"), 'name' => 'SMOKE Widget']], 'find_items q alone: a plain list (item_id, name)');
ok(tdata($BEA, 'find_items', ['q' => 'SMK', 'kind' => 'product'])['items'][0]['unit_price'] === '12.50', 'a code matches at its start; the price is a string with its scale');
$tx = tdata($BEA, 'find_tax_rates', ['q' => 'Sales']);
ok(count($tx) === 1 && $tx[0]['name'] === 'SMOKE Sales tax 8.25%' && tdata($BEA, 'find_tax_rates', ['include_archived' => false])['tax_rates'][0]['rate'] !== null, 'find_tax_rates: a plain list for q; the rates with their percentage otherwise');
ok(tdata($BEA, 'find_recurring', ['q' => 'rent']) === [['recurring_template_id' => $W['template'], 'name' => 'SMOKE Monthly rent']], 'find_recurring q alone: a plain list (recurring_template_id, name)');
$fr = tdata($BEA, 'find_recurring', ['recurring_template_id' => $W['template']]);
ok(count($fr['templates']) === 1 && $fr['templates'][0]['kind'] === 'journal' && count($fr['templates'][0]['template']['lines']) === 2 && $fr['templates'][0]['runs'] === [], 'one template: the document it drafts and its (no) runs');
ok(count(tdata($BEA, 'find_recurring', ['active' => false])['templates']) === 0 && count(tdata($BEA, 'find_recurring', ['kind' => 'journal', 'active' => true])['templates']) === 1, 'active/kind filters');
$rd = tdata($BEA, 'recurring_due', []);
ok($rd['count'] === 1 && $rd['due'][0]['recurring_template_id'] === $W['template'] && count(tdata($BEA, 'recurring_due', ['as_of' => '2026-09-30'])['due']) === 0, 'recurring_due: the template due since the 1st; none a day before');
echo "4. Dispatches, notifications, tokens\n";
q("INSERT INTO agent_dispatches (record_type, record_id, agent_member_id, kind, via, acting_member_id, status, reply_excerpt) VALUES ('bill', :b, 40, 'bill_attached', 'chat', 27, 'answered', 'SMOKE reply')", ['b' => $W['bill_h1']]);
$ad = tdata($CARL, 'agent_dispatches', ['record_type' => 'bill', 'record_id' => $W['bill_h1']]);
ok($ad['count'] === 1 && $ad['dispatches'][0]['agent_name'] === 'SMOKE Bookkeeper' && $ad['dispatches'][0]['status'] === 'answered' && $ad['dispatches'][0]['reply_excerpt'] === 'SMOKE reply', 'agent_dispatches: what was handed to which agent, how, and the reply');
ok(tdata($CARL, 'agent_dispatches', ['agent_member_id' => 40, 'since' => '2026-10-01'])['count'] === 1 && tdata($CARL, 'agent_dispatches', ['agent_member_id' => 41])['count'] === 0, 'by agent and since');
$mn = tdata($CARL, 'my_notifications', ['unread_only' => true]);
ok($mn['count'] === (int) val_as($CARL, 'SELECT count(*) FROM mcp_notifications WHERE read_at IS NULL') && $mn['count'] >= 1, 'my_notifications: Carl\'s own unread (' . $mn['count'] . ')');
ok(tdata($VERA, 'my_notifications', [])['count'] === (int) val_as($VERA, 'SELECT count(*) FROM mcp_notifications'), 'and each person only their own');
$mt = tdata($BEA, 'my_tokens', []);
ok(count($mt['tokens']) >= 1 && $mt['tokens'][0]['label'] === 'SMOKE p4' && !has_key($mt, 'token_hash') && !str_contains(json_encode($mt), ptoken($BEA)), 'my_tokens: the caller\'s own, label and scope, never the value');
finish();
